using System;
using System.Collections.Generic;
using UnityEngine;

namespace Cattas
{
    // Placeholder sound effects, generated by code (no sound files needed).
    // When the music & sound team delivers real sounds, these get swapped for recordings.
    public static class Sfx
    {
        public static float Volume = 0.6f;

        static AudioSource source;
        static readonly Dictionary<string, AudioClip> clips = new Dictionary<string, AudioClip>();
        static readonly Dictionary<string, float> lastPlayed = new Dictionary<string, float>();
        const int Rate = 44100;
        static System.Random rng = new System.Random(1234);

        public static void Init(GameObject host)
        {
            if (source != null) return;
            source = host.AddComponent<AudioSource>();
            source.playOnAwake = false;
            source.spatialBlend = 0f;
            BuildClips();
        }

        // Play a sound by name. minGap stops the same sound spamming when lots of cats do the same thing.
        public static void Play(string name, float volume = 1f, float minGap = 0.04f)
        {
            if (source == null || !clips.TryGetValue(name, out var clip)) return;
            float now = Time.unscaledTime;
            if (lastPlayed.TryGetValue(name, out float last) && now - last < minGap) return;
            lastPlayed[name] = now;
            source.pitch = 1f;
            source.PlayOneShot(clip, Volume * volume);
        }

        static float Noise() => (float)(rng.NextDouble() * 2.0 - 1.0);
        static float Sweep(float t, float f0, float f1, float dur) => Mathf.Sin(2f * Mathf.PI * (f0 * t + (f1 - f0) * t * t / (2f * dur)));
        static float Tone(float t, float f) => Mathf.Sin(2f * Mathf.PI * f * t);
        static float Decay(float t, float speed) => Mathf.Exp(-t * speed);
        static float Attack(float t, float time) => Mathf.Clamp01(t / time);

        static void Make(string name, float dur, Func<float, float> f)
        {
            int n = Mathf.Max(1, (int)(dur * Rate));
            var data = new float[n];
            float lp = 0f;
            for (int i = 0; i < n; i++)
            {
                float t = i / (float)Rate;
                float v = Mathf.Clamp(f(t), -1f, 1f);
                // fade the last few ms so nothing clicks
                float tail = Mathf.Clamp01((n - i) / (Rate * 0.004f));
                lp = v * tail;
                data[i] = lp;
            }
            var clip = AudioClip.Create(name, n, 1, Rate, false);
            clip.SetData(data, 0);
            clips[name] = clip;
        }

        static void BuildClips()
        {
            // a cat pops out of the hatch
            Make("pop", 0.12f, t => Sweep(t, 420f, 1100f, 0.12f) * Decay(t, 30f) * 0.6f);

            // a cat gets home: two-note chime
            Make("home", 0.45f, t =>
                (Tone(t, 1046.5f) * Decay(t, 9f) + (t > 0.09f ? Tone(t, 1568f) * Decay(t - 0.09f, 7f) : 0f)) * 0.35f);

            // clicking a trait onto a cat
            Make("click", 0.05f, t => Tone(t, 1800f) * Decay(t, 90f) * 0.5f);

            // scratching / digging dirt
            float lpS = 0f;
            Make("scratch", 0.06f, t => { lpS += (Noise() - lpS) * 0.35f; return lpS * Decay(t, 50f) * 0.9f; });

            // zoomies smashing through
            float lpZ = 0f;
            Make("smash", 0.14f, t => { lpZ += (Noise() - lpZ) * 0.15f; return (lpZ * 1.6f + Tone(t, 80f) * 0.4f) * Decay(t, 22f); });

            // hacking up a hairball: hrrk!
            float lpH = 0f;
            Make("hack", 0.22f, t =>
            {
                lpH += (Noise() - lpH) * 0.25f;
                float wob = 0.6f + 0.4f * Mathf.Sin(2f * Mathf.PI * 38f * t);
                return lpH * wob * Attack(t, 0.02f) * Decay(t, 9f) * 1.2f;
            });

            // ZAP!
            Make("zap", 0.5f, t =>
            {
                float buzz = Mathf.Sign(Mathf.Sin(2f * Mathf.PI * 60f * t)) * 0.4f + Mathf.Sign(Mathf.Sin(2f * Mathf.PI * 120f * t)) * 0.2f;
                return (buzz + Noise() * 0.7f) * Decay(t, 6f) * 0.55f;
            });

            // splat (too far to fall)
            float lpP = 0f;
            Make("splat", 0.3f, t => { lpP += (Noise() - lpP) * 0.08f; return (Sweep(t, 240f, 50f, 0.3f) * 0.7f + lpP * 1.5f) * Decay(t, 10f) * 0.7f; });

            // fluffchute puffing up
            float lpF = 0f;
            Make("puff", 0.25f, t => { lpF += (Noise() - lpF) * 0.05f; return lpF * 2.2f * Attack(t, 0.05f) * Decay(t, 10f); });

            // falling into water
            float lpW = 0f;
            Make("splash", 0.45f, t =>
            {
                lpW += (Noise() - lpW) * 0.3f;
                float bloop = Sweep(t, 600f, 180f, 0.45f) * Decay(t, 9f) * 0.35f;
                return (lpW * Decay(t, 7f) * 1.1f + bloop);
            });

            // singed on the hob
            Make("sizzle", 0.5f, t => Noise() * (0.5f + 0.5f * Mathf.Sin(2f * Mathf.PI * 90f * t)) * Attack(t, 0.02f) * Decay(t, 5f) * 0.5f);

            // something knocked over
            float lpC = 0f;
            Make("clatter", 0.35f, t =>
            {
                lpC += (Noise() - lpC) * 0.5f;
                float hits = (t < 0.04f || (t > 0.12f && t < 0.15f) || (t > 0.22f && t < 0.24f)) ? 1f : 0.15f;
                return (lpC * hits + Tone(t, 1700f) * 0.15f * Decay(t, 12f)) * Decay(t, 5f) * 0.8f;
            });

            // secret found: sparkly arpeggio
            Make("secret", 1.0f, t =>
            {
                float[] notes = { 783.99f, 987.77f, 1174.66f, 1567.98f, 1975.53f };
                float v = 0f;
                for (int i = 0; i < notes.Length; i++)
                {
                    float s = t - i * 0.07f;
                    if (s > 0f) v += Tone(s, notes[i]) * Decay(s, 5f);
                }
                return v * 0.18f;
            });

            // a switch / valve turned
            Make("clunk", 0.3f, t => (Tone(t, 140f) * 0.6f + Noise() * 0.3f) * Decay(t, 18f) + Noise() * 0.15f * Mathf.Clamp01(t - 0.05f) * Decay(t, 6f));

            // level complete jingle (C E G C)
            Make("win", 0.9f, t =>
            {
                float[] notes = { 523.25f, 659.25f, 783.99f, 1046.5f };
                float v = 0f;
                for (int i = 0; i < notes.Length; i++)
                {
                    float s = t - i * 0.12f;
                    if (s > 0f) v += (Tone(s, notes[i]) + 0.3f * Tone(s, notes[i] * 2f)) * Decay(s, 4.5f);
                }
                return v * 0.22f;
            });

            // level failed (sad trombone-ish)
            Make("lose", 1.0f, t =>
            {
                float[] notes = { 392f, 370f, 349.2f, 329.6f };
                int i = Mathf.Min(3, (int)(t / 0.22f));
                float s = t - i * 0.22f;
                float f = notes[i] * (i == 3 ? 1f + 0.02f * Mathf.Sin(2f * Mathf.PI * 6f * s) : 1f);
                float sq = Mathf.Sign(Mathf.Sin(2f * Mathf.PI * f * t)) * 0.3f + Tone(t, f) * 0.5f;
                return sq * Attack(s, 0.02f) * (i == 3 ? Decay(s, 2.5f) : 1f) * 0.25f;
            });
        }
    }
}
